import{GEOMETRY,WALKABLE}from'./architecture.js';
import{Game,validSave,distance}from'./engine.js';
import{ROOMS,RELICS,ZONES,DIRS,exitsFor}from'./content.js';
import{Renderer}from'./renderer.js';
import{Sound}from'./audio.js';
const $=id=>document.getElementById(id),key='hollowmere.journey.v2',oldKey='hollowmere.journey.v1',sound=new Sound(),modal=$('modal');
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let saved=null,legacy=null,storageOK=true,playing=false,walkTimer=null,holdTimer=null,saveTimer=null,icons={},lastAction=0,lastFrame=0,lastSecond=performance.now();
try{const raw=localStorage.getItem(key);if(raw&&validSave(JSON.parse(raw))){saved=JSON.parse(raw);if(saved.layoutRevision===undefined&&!localStorage.getItem('hollowmere.before-cloister'))localStorage.setItem('hollowmere.before-cloister',raw);}legacy=localStorage.getItem(oldKey);}catch{storageOK=false;}
let game=new Game(saved),renderer=new Renderer($('world'),game);
renderer.atlas.addEventListener('load',()=>{const sheet=renderer.atlas,s=sheet.width/4;for(const[id,r]of Object.entries(RELICS)){const c=document.createElement('canvas');c.width=c.height=80;c.getContext('2d').drawImage(sheet,r.sprite%4*s,Math.floor(r.sprite/4)*s,s,s,0,0,80,80);icons[id]=c.toDataURL();}update();});
function icon(id){return icons[id]?`<img class="relic-icon" src="${icons[id]}" alt="">`:'<span class="relic-icon" aria-hidden="true">✧</span>';}
function stopWalk(){clearInterval(walkTimer);walkTimer=null;renderer.target=null;}
function stopHold(){clearTimeout(holdTimer);holdTimer=null;document.querySelectorAll('.held').forEach(b=>b.classList.remove('held'));}
function save(immediate=false){clearTimeout(saveTimer);const write=()=>{const snapshot=game.snapshot();try{localStorage.setItem(key,JSON.stringify(snapshot));saved=snapshot;storageOK=true;$('save-indicator').textContent='Journey saved';}catch{storageOK=false;$('save-indicator').textContent='Export save from menu';}};if(immediate)write();else saveTimer=setTimeout(write,180);}
function show(eyebrow,title,copy,buttons=''){stopWalk();stopHold();$('modal-content').innerHTML=`<button class="modal-close" aria-label="Close dialog">×</button><div class="modal-eyebrow">${escape(eyebrow)}</div><h3 class="modal-title">${escape(title)}</h3><div class="modal-copy">${copy}</div>${buttons}`;$('modal-content').querySelector('.modal-close').onclick=()=>modal.close();if(!modal.open)modal.showModal();}
function update(){const s=game.state,r=game.room;$('region-label').textContent=ZONES[r.zone]?.name||'The sanctuary';$('room-title').textContent=r.name;$('hearts').textContent=s.world.lanternAt?'Lantern resting':'Lantern lit';$('hearts').setAttribute('aria-label',$('hearts').textContent);$('quest').textContent='';$('room-number').textContent='';$('room-state').textContent='';
 $('relic-bar').innerHTML=s.relics.map((id,i)=>`<button class="relic ${s.equipped===id?'active':''}" data-relic="${id}" aria-label="Equip ${RELICS[id].name}" aria-pressed="${s.equipped===id}">${icon(id)}<span>${RELICS[id].short}</span><span class="relic-key">${i+1}</span></button>`).join('');
 $('relic-bar').querySelectorAll('[data-relic]').forEach(b=>b.onclick=()=>doAction(()=>game.equip(b.dataset.relic)));
 $('use').textContent='Use '+RELICS[s.equipped].short.toLowerCase();$('undo').disabled=!game.history.length;
 const o=game.nearest();$('action-label').textContent=o?({cord:'Pull',shade:'Turn',damper:'Turn',stand:s.world.lanternAt===s.room+':'+o.id?'Take':'Interact',cabinet:s.world.cabinetOpen&&!game.has('blade')?'Take':'Open',binding:s.equipped==='blade'?'Cut':'Inspect'})[o.type]||'Inspect':'Interact';$('action-icon').textContent=o?.type==='cord'?'↓':'✧';
}
function observationArt(o){if(!o||o.furnishing===undefined||!renderer.furnitureReady)return;const canvas=document.createElement('canvas');canvas.width=canvas.height=180;canvas.className='observation-art';canvas.setAttribute('aria-hidden','true');let index=o.furnishing;const w=game.state.world;if(o.type==='cabinet')index=w.cabinetOpen?1:0;if(o.type==='cord')index=w.cords[o.index]?2:3;if(['shade','shutter'].includes(o.type))index=w.shadeClosed?4:5;const cell=renderer.furniture.width/4;canvas.getContext('2d').drawImage(renderer.furniture,index%4*cell,Math.floor(index/4)*cell,cell,cell,0,0,180,180);$('modal-content').querySelector('.modal-copy').prepend(canvas);}
function flush(){for(const e of game.events.splice(0)){if(e.text)$('message').textContent=e.text;if(['reveal','click','relic','cut','discovery'].includes(e.type))sound.chime(e.type);if(e.type==='cut')renderer.burst(game.state.x,game.state.y,'#8bae88',12);if(e.type==='arrive'){stopWalk();const el=$('room-arrival');el.textContent=e.text;el.classList.remove('arrive');void el.offsetWidth;el.classList.add('arrive');}if(e.type==='inspect'){show('An observation',e.title,`<p>${escape(e.text)}</p>${e.boundary?'<p class="chapter-boundary">This passage continues beyond the seven rooms in this opening chapter.</p>':''}`);observationArt(game.data.objects.find(o=>o.name===e.title));}if(e.type==='relic')show('Recovered',RELICS[e.relic].name,`${icon(e.relic)}<p>${escape(e.text)}</p>`);}update();if(playing)save();}
function doAction(fn){if(!playing||modal.open)return;stopWalk();fn();flush();}
function refreshTitle(){$('continue').hidden=!saved;$('begin').textContent=saved?'Begin again':'Enter Hollowmere';$('begin').className=saved?'secondary':'primary';$('save-summary').textContent=saved?`${ROOMS[saved.room].name} · ${Math.floor(saved.seconds/60)} minutes`:'Opening chapter · Seven rooms. Your journey saves as you go.';if(!storageOK)$('save-summary').textContent='Browser storage is unavailable. Export your journey from the menu.';}
function start(fresh=false){clearTimeout(saveTimer);if(fresh){game=new Game();renderer.game=game;}playing=true;$('title-screen').hidden=true;$('play-screen').hidden=false;modal.close();renderer.lastRoom='';lastSecond=performance.now();$('message').textContent=game.room.arrival;update();save(true);}
function confirmNew(){if(!saved)return start(true);show('Begin again','A new journey?',`<p>This replaces your opening-chapter journey. Export it from the pause menu first if you want to keep it.</p>`,`<div class="modal-buttons"><button class="secondary" id="cancel-new">Keep exploring</button><button class="primary" id="confirm-new">Begin again</button></div>`);$('cancel-new').onclick=()=>modal.close();$('confirm-new').onclick=()=>start(true);}
function help(){show('Controls','Finding your way',`<p>Tap the floor to walk, or use the direction buttons. Tap an object to approach it; <strong>Interact</strong> operates it. The <strong>◎</strong> button examines something within reach without operating it.</p><p>Select a relic, then use its button. With the lantern selected, interacting with a reading stand sets it down. Interact with that stand again to take it back.</p><p>Walk against a wheeled object to push it. Undo returns an action, including changes in other rooms.</p><p>The journal keeps observations you have inspected and any notes you write. The map records passages you have walked.</p><p class="help-keys">Arrows / WASD: move · E / Enter: interact · R: inspect · Space: use relic · 1 / 2: equip · Z: undo · M: map · J: journal · Esc: pause.</p><p class="fine">This opening chapter contains seven rooms. Passages beyond it are identified when inspected. Progress is saved on this browser; export a save to keep a backup.</p>`);}
function journal(){show('Field notes','The Keeper’s Journal',`<label class="notes-label" for="personal-notes">Your notes</label><textarea id="personal-notes" maxlength="4000" rows="4" placeholder="Leave a thought here…">${escape(game.state.notes)}</textarea><p class="fine">Notes save as you write.</p>${game.state.observations.length?game.state.observations.map(e=>`<div class="journal-entry"><strong>${escape(e.title)}</strong><span class="fine">${escape(ROOMS[e.room].name)}</span>${e.texts.map(t=>`<p>${escape(t)}</p>`).join('')}</div>`).join(''):'<p>No observations recorded yet.</p>'}`);$('personal-notes').oninput=e=>{game.state.notes=e.target.value;save();};}
function miniPlan(r){let tiles='';for(let y=0;y<13;y++)for(let x=0;x<17;x++){const t=GEOMETRY[r.id][y][x];if(t==='D'&&!exitsFor(r.id).some(e=>e.at[0]===x&&e.at[1]===y&&game.state.connections.includes([r.id,e.to].sort().join(':'))))continue;const color=t==='D'?'#e5c489':WALKABLE.has(t)?'#91a69a':t==='#'?'#476264':t==='r'?'#567367':null;if(color)tiles+=`<rect x="${x}" y="${y}" width="1" height="1" fill="${color}"/>`;}if(r.id===game.state.room)tiles+=`<circle cx="${game.state.x+.5}" cy="${game.state.y+.5}" r=".65" fill="#ffd88d"/>`;return`<svg viewBox="0 0 17 13" aria-hidden="true">${tiles}</svg>`;}
function map(){const seen=game.state.visited;let cells='';for(let y=0;y<3;y++)for(let x=-1;x<2;x++){const r=Object.values(ROOMS).find(r=>r.coord[0]===x&&r.coord[1]===y);cells+=r&&seen.includes(r.id)?`<button class="map-room ${r.id===game.state.room?'current':''}" data-room="${r.id}">${miniPlan(r)}<span>${escape(r.name)}</span></button>`:'<div></div>';}
 show('Walked passages','Hollowmere',`<div class="opening-map">${cells}</div><div class="known-passages">${game.state.connections.map(edge=>{const[a,b]=edge.split(':');return`<p>${escape(ROOMS[a].name)} ↔ ${escape(ROOMS[b].name)}</p>`;}).join('')}</div><p class="fine">Only rooms and passages you have visited are recorded.</p>`);
 document.querySelectorAll('[data-room]').forEach(b=>b.onclick=()=>{const r=ROOMS[b.dataset.room];show('A place remembered',r.name,`<p>${escape(r.arrival)}</p>`,`<div class="modal-buttons"><button class="secondary" id="back-map">Back to map</button></div>`);$('back-map').onclick=map;});}
function download(text,name){const url=URL.createObjectURL(new Blob([text],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function menu(){show('Take a breath','The journey can wait',`<p class="fine">Opening chapter · Seven rooms</p><div class="menu-list"><button id="resume">Continue exploring</button><button id="sound-toggle">Sound: ${sound.enabled?'on':'off'}</button><button id="menu-help">Controls</button><button id="export">Export journey</button><button id="import">Import journey</button>${legacy?'<button id="export-legacy">Export previous campaign save</button>':''}<button id="quit">Save & return to title</button></div>`);$('resume').onclick=()=>modal.close();$('sound-toggle').onclick=async()=>{await sound.toggle();menu();};$('menu-help').onclick=help;$('export').onclick=()=>{save(true);download(JSON.stringify(game.snapshot(),null,2),'hollowmere-opening-journey.json');};$('import').onclick=importSave;if($('export-legacy'))$('export-legacy').onclick=()=>download(legacy,'hollowmere-previous-campaign.json');$('quit').onclick=()=>{save(true);playing=false;modal.close();$('play-screen').hidden=true;$('title-screen').hidden=false;refreshTitle();};}
function importSave(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{const f=input.files?.[0];if(!f)return;if(f.size>250000)throw Error('This file is too large to be a journey.');const data=JSON.parse(await f.text());if(data.version===1)throw Error('This is a previous-campaign save. It remains separate from the new opening chapter.');if(!validSave(data))throw Error('This file is not a valid opening-chapter journey.');const candidate=new Game(data);show('Import journey','Continue this journey?',`<p>${escape(ROOMS[data.room].name)} · ${Math.floor(data.seconds/60)} minutes</p><p>This replaces your current opening-chapter journey.</p>`,`<div class="modal-buttons"><button class="secondary" id="cancel-import">Cancel</button><button class="primary" id="apply-import">Import</button></div>`);$('cancel-import').onclick=menu;$('apply-import').onclick=()=>{clearTimeout(saveTimer);game=candidate;renderer.game=game;renderer.lastRoom='';modal.close();$('message').textContent=game.room.arrival;update();save(true);};}catch(e){show('Journey not imported','Keep your lantern',`<p>${escape(e.message)}</p><p>Your current journey has not changed.</p>`);}};input.click();}
function findPath(goal){const s=game.state,queue=[[s.x,s.y]],seen=new Set([`${s.x},${s.y}`]),parents=new Map();let end=null;while(queue.length){const[x,y]=queue.shift();if(goal(x,y)){end=[x,y];break;}for(const[dx,dy]of Object.values(DIRS)){const nx=x+dx,ny=y+dy,k=`${nx},${ny}`;if(seen.has(k)||!game.passable(nx,ny))continue;if(game.tile(nx,ny)==='D'&&!goal(nx,ny))continue;seen.add(k);parents.set(k,[x,y]);queue.push([nx,ny]);}}if(!end)return null;const path=[];while(end[0]!==s.x||end[1]!==s.y){path.unshift(end);end=parents.get(end.join(','));}return path;}
function tapWorld(e){if(!playing||modal.open)return;stopWalk();const p=renderer.point(e);if(p.x<0||p.y<0||p.x>=17||p.y>=13)return;const object=renderer.hitObject(p);if(object){p.x=object.x;p.y=object.y;}if(object&&distance(game.state,object)<=1){game.inspect(object);flush();return;}const goal=object?(x,y)=>distance({x,y},object)===1:(x,y)=>x===p.x&&y===p.y;const path=findPath(goal);if(!path){game.say('There is no clear walking path.');flush();return;}renderer.target=p;let index=0;const room=game.state.room;walkTimer=setInterval(()=>{if(modal.open||game.state.room!==room){stopWalk();return;}if(index>=path.length){stopWalk();if(object){game.state.face=p.x>game.state.x?[1,0]:p.x+(object.w||1)-1<game.state.x?[-1,0]:p.y>game.state.y?[0,1]:[0,-1];game.say(game.describe(object));flush();}return;}const next=path[index++];if(!game.move(next[0]-game.state.x,next[1]-game.state.y))stopWalk();flush();},110);}
$('world').addEventListener('pointerdown',tapWorld);
document.querySelectorAll('[data-dir]').forEach(b=>{const[dx,dy]=b.dataset.dir.split(',').map(Number);b.addEventListener('pointerdown',e=>{if(!playing||modal.open)return;e.preventDefault();stopWalk();stopHold();b.setPointerCapture(e.pointerId);b.classList.add('held');doAction(()=>game.move(dx,dy));const repeat=()=>{doAction(()=>game.move(dx,dy));holdTimer=setTimeout(repeat,130);};holdTimer=setTimeout(repeat,280);});for(const event of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(event,stopHold);});
$('interact').onclick=()=>doAction(()=>game.interact());$('use').onclick=()=>doAction(()=>game.use());$('inspect').onclick=()=>doAction(()=>game.inspect());$('undo').onclick=()=>doAction(()=>game.undo());$('menu').onclick=menu;$('journal').onclick=journal;$('map').onclick=map;$('controls-help').onclick=help;$('begin').onclick=confirmNew;$('continue').onclick=()=>start();$('title-help').onclick=help;$('title-sound').onclick=async()=>{await sound.toggle();$('title-sound').textContent=sound.enabled?'♫':'♪';$('title-sound').setAttribute('aria-label',sound.enabled?'Disable sound':'Enable sound');};
window.addEventListener('keydown',e=>{if(['TEXTAREA','INPUT'].includes(e.target.tagName))return;if(e.key==='Escape'){if(playing&&!modal.open){e.preventDefault();menu();}return;}if(!playing||modal.open||e.ctrlKey||e.metaKey||e.altKey)return;const k=e.key.toLowerCase(),moves={arrowup:[0,-1],w:[0,-1],arrowdown:[0,1],s:[0,1],arrowleft:[-1,0],a:[-1,0],arrowright:[1,0],d:[1,0]};if(moves[k]){e.preventDefault();if(performance.now()-lastAction<90)return;lastAction=performance.now();doAction(()=>game.move(...moves[k]));return;}if([' ','enter','e','z','m','j','r','1','2'].includes(k))e.preventDefault();if(e.repeat)return;if(k===' ')$('use').click();if(k==='enter'||k==='e')$('interact').click();if(k==='z')$('undo').click();if(k==='r')$('inspect').click();if(k==='m')map();if(k==='j')journal();if(/^[12]$/.test(k))doAction(()=>game.equip(Object.keys(RELICS)[Number(k)-1]));});
window.addEventListener('blur',()=>{stopWalk();stopHold();if(playing)save(true);});document.addEventListener('visibilitychange',()=>{stopWalk();stopHold();if(playing)save(true);lastSecond=performance.now();});window.addEventListener('pagehide',()=>{if(playing)save(true);});
function frame(now){if(playing&&!document.hidden){if(now-lastFrame>=32){renderer.draw(now);lastFrame=now;}sound.update();if(now-lastSecond>=1000){if(!modal.open){game.state.seconds+=Math.floor((now-lastSecond)/1000);if(game.state.seconds%30===0)save();}lastSecond=now;}}else lastSecond=now;requestAnimationFrame(frame);}refreshTitle();update();requestAnimationFrame(frame);

// The title describes the code actually loaded, not merely the current server manifest.
$('check-update').onclick=()=>{if(playing)save(true);const url=new URL(location.href);if(url.pathname.includes('/releases/'))url.pathname=url.pathname.split('/releases/')[0]+'/';url.searchParams.set('launch',Date.now());location.replace(url.href);};
window.addEventListener('pageshow',event=>{if(event.persisted&&!playing)location.reload();});
